import {arr,unique,YEAR_BASES,TRACK_NAMES,AUDIT_NAMES,TENURE_NAMES,EVIDENCE_NAMES,labelRegion,recordYear,canonicalLabel,outcomeOf,selectStudyRecords,summarizeStudy,comparisonRows,flowRows,observationSummary,normalizedJobs,filterJobs,jobState,datasetCsv} from './observatory-logic.js?v=1.0.0';

const mounted=new WeakMap();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=value=>{try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null}catch{return null}};
const sourceLink=(s,label)=>{const url=safeUrl(typeof s==='string'?s:s?.url);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label||s.label||new URL(url).hostname)}</a>`:'<span class="muted">来源链接待核验</span>'};
const sources=(items=[])=>arr(items).length?`<ul class="obs-sources">${arr(items).map(s=>`<li>${sourceLink(s)}</li>`).join('')}</ul>`:'<span class="muted">没有已关联的公开来源</span>';
const ratio=(a,b)=>b?`${a} / ${b} · ${Math.round(a/b*100)}%`:`${a} / 0 · 无可比样本`;
const badge=(s,t='')=>`<span class="tag ${t}">${esc(s)}</span>`;
const panel=(title,sub,body,extra='')=>`<section class="panel obs-panel ${extra}"><div class="panel-heading"><div><p class="eyebrow">${esc(sub)}</p><h2>${esc(title)}</h2></div></div>${body}</section>`;
const note=text=>`<p class="chart-note">${text}</p>`;
function head(title,sub,asOf){return `<div class="page-top"><div><p class="eyebrow">MARKET OBSERVATORY / RESEARCH DESK</p><h1>${esc(title)}<span class="title-dot">.</span></h1><p class="page-subtitle">${sub}</p></div><span class="outline-badge">观察截至 ${esc(asOf||'未记录')}</span></div>`;}
function stat(label,value,detail,action=''){return `<${action?'button':'article'} ${action?'type="button"':''} class="obs-stat" ${action}><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail)}</small></${action?'button':'article'}>`;}
function field(name,label,options,value){return `<label class="filter-label">${esc(label)}<select name="${esc(name)}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function searchField(name,label,value){return `<label class="filter-label">${esc(label)}<input class="obs-input" type="search" name="${esc(name)}" value="${esc(value)}" placeholder="输入关键词"></label>`;}
function actions(kind,label='当前筛选'){return `<div class="obs-actions"><span class="muted">导出${esc(label)}，包含观察日期与筛选口径</span><button class="button secondary" type="button" data-obs-export="${esc(kind)}" data-format="csv">CSV</button><button class="button secondary" type="button" data-obs-export="${esc(kind)}" data-format="json">JSON</button></div>`;}
function empty(text){return `<div class="empty-state"><span aria-hidden="true">∅</span><h3>${esc(text)}</h3><p>资料不足、未知信息和未开始核验分别保留。可调整筛选或查看覆盖来源。</p></div>`;}
function personButton(person){return `<button class="person-button" type="button" data-obs-person="${esc(person.id)}">${esc(person.name||person.id)}</button>`;}
function peopleTable(rows,observatory,basis='first'){return rows.length?`<div class="table-scroll"><table class="obs-table"><caption class="obs-sr-only">对应研究者与已知去向</caption><thead><tr><th scope="col">研究者 / 培养项目</th><th scope="col">年份资料</th><th scope="col">所选去向</th><th scope="col">岗位证据</th></tr></thead><tbody>${rows.map(r=>{const p=outcomeOf(r,basis,observatory);return `<tr><td>${personButton(r)}<span class="cell-note">${esc(r.school)}<br>${esc(r.program)}</span></td><td>名单 ${esc(r.source_cohort_year||'未知')}<br>毕业 ${esc(r.graduation_year||'未知')}<br>首职 ${esc(r.placement_year||'未知')}<span class="cell-note">${esc(r.market_cycle||'求职季未知')}</span></td><td>${esc(p.destination||'去向待核验')}<span class="cell-note">${esc(p.role||'职位待核验')}<br>${esc(p.department||'院系待核验')}</span></td><td>${badge(TENURE_NAMES[p.tenure_status]||p.tenure_status||'Tenure 未知')}${badge(EVIDENCE_NAMES[p.tenure_evidence_status]||p.tenure_evidence_status||'证据未知')}<span class="cell-note">${p.basis==='final_verified'?'最终安排独立记录':'沿用首次岗位'}</span></td></tr>`}).join('')}</tbody></table></div>`:empty('当前筛选没有已收录人员');}
function saveFile(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportRows(kind,format,rows,meta,columns){if(format==='json')saveFile(`observatory-${kind}-${meta.as_of||'archive'}.json`,JSON.stringify({schema_version:'1.0',metadata:meta,count:rows.length,records:rows},null,2),'application/json;charset=utf-8');else saveFile(`observatory-${kind}-${meta.as_of||'archive'}.csv`,datasetCsv(rows,columns,meta),'text/csv;charset=utf-8');}
function currentParams(){return new URLSearchParams(typeof location==='undefined'?'':location.hash.split('?').slice(1).join('?'));}
function persist(view,state){const params=new URLSearchParams();for(const [key,value] of Object.entries(state))if(value!==null&&value!==undefined&&value!==''&&value!=='all'&&key!=='page')params.set(key,Array.isArray(value)?value.join(','):String(value));if(state.page&&state.page!=='1')params.set('page',state.page);history.replaceState(null,'',`${location.pathname}${location.search}#${view}${params.size?'?'+params:''}`);}
function restore(defaults){const p=currentParams();const state={...defaults};for(const key of Object.keys(defaults)){if(p.has(key))state[key]=Array.isArray(defaults[key])?unique(p.get(key).split(',')):p.get(key);}return state;}
function withFocus(root,render){const active=document.activeElement;const previous=active&&root.contains(active)?{name:active.name,value:active.value,selection:typeof active.selectionStart==='number'?active.selectionStart:null}:null;render();if(previous?.name){const candidate=[...root.querySelectorAll('[name]')].find(el=>el.name===previous.name&&(el.type!=='checkbox'||el.value===previous.value));if(candidate){candidate.focus({preventScroll:true});if(previous.selection!==null&&candidate.setSelectionRange)try{candidate.setSelectionRange(previous.selection,previous.selection)}catch{}}}}
function bindRoot(root,handler){const abort=new AbortController();mounted.set(root,abort);for(const type of ['click','change','input','submit'])root.addEventListener(type,e=>handler(type,e),{signal:abort.signal});}
export function unmountObservatory(root){mounted.get(root)?.abort();mounted.delete(root);delete root.dataset.observatoryView;}

function dateText(value,precision){return value?`${value}${precision==='year'?'（仅年份）':precision==='month'?'（仅月份）':''}`:'日期未核验';}
function sourceCheckMarkup(observatory){
 const checks=observatory.source_checks||{},rows=arr(checks.sources);const last=checks.last_run;
 const recent=last?rows.filter(s=>s.fetched_at===last):[];
 return panel('来源可用性与变化检测','MONITOR SOURCES, REVIEW THE FACTS',`<div class="obs-body"><p>最近一次运行：<strong>${esc(last||'尚未运行 / 尚未建立在线基线')}</strong>。累计缓存 ${rows.length} 个来源；本轮选择 ${checks.selected??recent.length} 个，发现 ${recent.filter(s=>s.changed).length} 个变化、${recent.filter(s=>s.error).length} 个读取失败。</p><p>首次成功抓取建立基线；后续变化或读取失败进入待核验队列。缓存保留原哈希、ETag、最后修改时间和历史记录，不直接改写人员事实。</p>${checks.policy?`<p>${esc(checks.policy)}</p>`:''}</div>${rows.length?actions('sources','全部来源检测记录')+`<details class="obs-body"><summary>查看抓取记录 · 前 ${Math.min(50,rows.length)} / ${rows.length} 个来源</summary><div class="table-scroll"><table class="obs-table"><thead><tr><th scope="col">来源</th><th scope="col">最近抓取</th><th scope="col">HTTP / 提取</th><th scope="col">变化 / 异常</th></tr></thead><tbody>${rows.slice(0,50).map(s=>`<tr><td>${sourceLink(s)}<span class="cell-note">${esc(s.last_success_at?'最近成功 '+s.last_success_at:'尚无成功抓取')}</span></td><td>${esc(s.fetched_at||'未抓取')}</td><td>${esc(s.http_status??'未知')}<span class="cell-note">${esc(s.extraction||s.content_type||'内容类型未知')}</span></td><td>${s.error?esc(s.error):s.changed?'检测到变化，等待核验':'未检测到变化 / 首次基线'}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="obs-body muted">当前发布尚无来源抓取缓存。可运行维护命令建立基线，定时检查的报告会作为 GitHub Actions 产物保留。</p>'}`);
}
const EVENT_STATUS_NAMES={recorded_degree:'学位资料记录',placed:'任职资料记录',legacy_record:'历史任职记录',on_market:'公开求职中',announced_future:'已宣布，尚未开始',announced:'已宣布安排',observed_current:'核验时现职',current_at_check:'核验时现职',current:'资料所示现职',active:'仍在任职',ongoing:'仍在任职',deferred:'明确延期重新求职',unknown:'状态待核验'};
const EVENT_NAMES={graduation:'博士毕业',market:'公开求职季',first_job:'首次岗位',final_arrangement:'该次求职最终安排',subsequent_job:'后续任职',current_appointment:'已观察到的现职'};
function displayEventGroups(personId,observatory){
 const events=arr(observatory.events).filter(e=>e.person_id===personId).sort((a,b)=>String(a.start||'9999').localeCompare(String(b.start||'9999')));
 const grouped=[];
 for(const event of events){
  const appointment=['first_job','final_arrangement','subsequent_job','current_appointment'].includes(event.type);
  const future=['announced_future','announced'].includes(event.status);
  const match=appointment&&event.start&&event.institution&&event.title?grouped.find(e=>e.appointment&&e.future===future&&e.start===event.start&&e.end===event.end&&e.institution===event.institution&&e.title===event.title):null;
  if(match){match.types=unique([...match.types,event.type]);match.statuses=unique([...match.statuses,event.status]);match.source_urls=unique([...match.source_urls,...arr(event.source_urls)]);match.claim_ids=unique([...match.claim_ids,...arr(event.claim_ids)]);match.event_ids.push(event.id);}
  else grouped.push({...event,appointment,future,types:[event.type],statuses:[event.status],source_urls:[...arr(event.source_urls)],claim_ids:[...arr(event.claim_ids)],event_ids:[event.id]});
 }
 return grouped;
}
function fieldName(field){
 const names={school:'博士培养院校',program_id:'博士培养项目',program:'学位项目名称',origin:'培养地区',graduation_year:'博士毕业年份',placement_year:'首次入职年份',source_cohort_year:'来源名单年份',market_cycle:'公开求职季',destination:'首次岗位机构',role:'首次岗位职称',tracks:'研究方向',topics:'研究主题',methods:'研究方法',homepage:'个人主页',cv_url:'本人 CV',jmp:'Job Market Paper',jmp_url:'JMP 来源',institution:'机构',institution_id:'规范机构',title:'官方职位 / 学位名称',start:'开始时间',end:'结束时间',department:'院系',region:'地区',tenure_status:'Tenure 状态',tenure_evidence_status:'岗位证据状态',status:'状态',undergraduate:'本科教育',identity:'公开身份资料',research_classification:'研究分类依据',field_evidence:'研究分类依据',final_placement:'最终求职安排',subsequent:'后续任职'};
 const parts=String(field||'').split('.');
 if(parts[0]==='events')return '职业事件 · '+(EVENT_NAMES[parts[1]]||'已记录事件')+' · '+(names[parts.at(-1)]||'相关资料');
 return parts.filter(p=>!/^\d+$/.test(p)).map(p=>names[p]||p).join(' · ');
}
function fieldValue(claim,person,observatory){
 if(claim.field==='program_id')return person?.program||arr(observatory.institutions).find(i=>i.id===claim.value)?.name||'培养项目资料';
 if(['tracks','topics','methods'].includes(claim.field))return arr(claim.value).map(v=>canonicalLabel(observatory,claim.field,v)).join(' · ')||'尚未分类';
 const value=claim.value;
 if(value===null||value===undefined)return '资料未核验';
 if(typeof value==='boolean')return value?'是':'否';
 if(Array.isArray(value))return value.map(v=>typeof v==='object'?JSON.stringify(v):v).join(' · ');
 return typeof value==='object'?JSON.stringify(value):String(value);
}
export function personTimelineMarkup(personId,observatory={}){
 const events=displayEventGroups(personId,observatory);
 return `<section class="obs-person-section"><h3>职业事件时间线</h3><p class="muted">时间按原始资料精度显示。现职、未来安排与最初 placement 分别记录；缺少结束日期不自动表示持续任职。同一时间与职位的重复事件合并展示，保留各类语义及全部证据。</p>${events.length?`<ol class="obs-timeline">${events.map(e=>`<li><p class="obs-event-date">${esc(dateText(e.start,e.date_precision))}${e.end?' — '+esc(e.end):''}</p><h4>${e.types.map(t=>esc(EVENT_NAMES[t]||'职业资料记录')).join(' / ')}</h4><p>${esc(e.institution||'机构待核验')}${e.department?' · '+esc(e.department):''}</p><p>${esc(e.title||'')}${e.statuses.map(status=>badge(EVENT_STATUS_NAMES[status]||'资料记录')).join('')}</p>${e.appointment&&e.tenure_status?`<p>${badge(TENURE_NAMES[e.tenure_status]||e.tenure_status)}${badge(EVIDENCE_NAMES[e.tenure_evidence_status]||e.tenure_evidence_status||'尚未确认')}</p>`:''}<details><summary>事件来源与依据</summary>${sources(e.source_urls)}${arr(e.claim_ids).length?`<p class="muted">关联证据 ${e.claim_ids.length} 条，见下方字段证据。</p>`:''}<p class="muted">原始事件标识：${esc(e.event_ids.join(' · '))}</p>${e.checked_at?`<p class="muted">核验日期：${esc(e.checked_at)}</p>`:''}</details></li>`).join('')}</ol>`:'<p class="muted">尚无可构建的职业事件。既有来源仍保留在原始档案中。</p>'}</section>`;
}
export function personClaimsMarkup(personId,observatory={}){
 const claims=arr(observatory.claims).filter(c=>c.person_id===personId);const person=arr(observatory.people).find(p=>p.id===personId);
 return `<section class="obs-person-section"><h3>字段证据与核验状态</h3><p class="muted">“历史来源关联”表示迁移保留的来源链接，尚不等于逐字段原文核验。引用、核验时间与冲突分别展示。</p>${claims.length?`<div class="obs-claims">${claims.map(c=>`<details class="obs-claim"><summary><strong>${esc(fieldName(c.field))}</strong> ${badge(EVIDENCE_NAMES[c.status]||'核验状态待确认')} ${esc(fieldValue(c,person,observatory))}</summary><p class="muted">原始字段：<code>${esc(c.field)}</code></p>${c.quote?`<blockquote>${esc(c.quote)}</blockquote>`:'<p class="muted">尚无已保存的原文摘录。</p>'}${c.conflict?`<p class="obs-warning">${esc(typeof c.conflict==='string'?c.conflict:JSON.stringify(c.conflict))}</p>`:''}${sources(c.source_urls)}<dl class="obs-inline-dl"><dt>来源日期</dt><dd>${esc(c.source_date||'未记录')}</dd><dt>抓取日期</dt><dd>${esc(c.fetched_at||'未记录')}</dd><dt>核验日期</dt><dd>${esc(c.checked_at||'未记录')}</dd></dl></details>`).join('')}</div>`:'<p class="muted">尚无字段级证据；不自动将旧备注升级为确认。</p>'}</section>`;
}

function studyControls(state,records,options={}){
 const years=unique(records.map(r=>recordYear(r,state.year_basis))).sort((a,b)=>b-a);
 return `<div class="obs-filter-grid">${field('year_basis','比较时间口径',Object.entries(YEAR_BASES),state.year_basis)}${field('year','年份',[['all','全部已收录年份'],...years.map(y=>[String(y),String(y)])],state.year)}${field('track','研究方向',[['all','全部方向'],...Object.entries(TRACK_NAMES)],state.track)}${field('basis','岗位观察',[['first','首次岗位'],['final','已确认最终安排 / 沿用首职']],state.basis)}${field('complete_only','名册完整性',[['all','全部已收录人员'],['true','仅来自已确认完整的名册']],state.complete_only)}${field('tenure','Tenure 证据筛选',[['all','所有核验状态'],['confirmed','仅明确确认'],['inferred','仅规则推定'],['title_explicit','仅职位原文明确'],['unknown','仅未知状态']],state.tenure)}${field('provisional','研究分类',[['exclude','仅当前归档标签'],['include','加入有依据的暂定标签']],state.provisional)}${options.region?field('region','博士培养地区',[['all','全部地区'],...unique(records.map(r=>r.origin)).map(r=>[r,labelRegion(r)])],state.region):''}</div>`;
}
function observationPanel(records,observatory){return panel('固定观察窗口：毕业后第一年 / 第三年','CAREER WINDOWS',`<div class="obs-window-grid">${[1,3].map(n=>{const s=observationSummary(records,observatory,n);return `<article><h3>毕业后第 ${n} 个日历年</h3><strong>${s.known} <small>/ ${s.total} 人可核验窗口内岗位</small></strong><dl>${[['observed','岗位覆盖窗口已确认'],['not_yet_observed','尚未观察满整个日历年'],['graduation_unknown','毕业年份未知'],['date_or_continuity_unknown','任职日期 / 持续性不足'],['path_unknown','窗口内履历缺失'],['multiple_appointments','多份岗位需进一步厘清'],['as_of_unknown','观察日期未知']].map(([key,label])=>`<div><dt>${label}</dt><dd>${s.counts[key]||0}</dd></div>`).join('')}</dl><details><summary>查看逐人观察状态</summary><ul class="obs-compact-list">${s.rows.map(r=>{const person=records.find(p=>p.id===r.person_id);return `<li>${personButton(person)} · ${r.year||'年份未知'} · ${esc(({observed:'窗口内已确认',not_yet_observed:'尚未观察满',graduation_unknown:'毕业年未知',date_or_continuity_unknown:'日期或持续性未知',path_unknown:'履历缺失',multiple_appointments:'多岗位待厘清',as_of_unknown:'观察日期未知'})[r.status])}${r.event?' · '+esc(r.event.institution)+' / '+esc(r.event.title):''}</li>`}).join('')}</ul></details></article>`}).join('')}</div>${note('采用保守日历年窗口：只对观察已覆盖整个目标年份、且任职证据能够覆盖该窗口的人计入已确认。年级日期不换算为精确周年；历史首职没有结束信息时，不自动延续到第三年。')}`);}

function mountCompare(ctx){
 const {root,records,catalog,observatory}=ctx;const knownPrograms=new Set(records.map(r=>r.program_id));const programs=arr(catalog.programs).filter(p=>knownPrograms.has(p.id)).sort((a,b)=>a.school.localeCompare(b.school)||a.id.localeCompare(b.id));
 const state=restore({programs:(['university-of-pennsylvania-marketing','university-of-chicago-marketing'].every(id=>programs.some(p=>p.id===id))?['university-of-pennsylvania-marketing','university-of-chicago-marketing']:programs.slice(0,2).map(p=>p.id)),year_basis:'source',year:'all',track:ctx.filters?.track||'all',basis:ctx.filters?.basis||'first',complete_only:'all',tenure:'all',provisional:'exclude',program_query:'',detail:''});state.programs=unique(state.programs).filter(id=>arr(catalog.programs).some(p=>p.id===id)).slice(0,5);
 let comparison=[],selected=[];
 function render(){comparison=comparisonRows(records,catalog,observatory,state);selected=selectStudyRecords(records,catalog,observatory,state);const available=arr(catalog.programs).filter(p=>!state.program_query||[p.school,p.kind,p.region].join(' ').toLowerCase().includes(state.program_query.toLowerCase())).sort((a,b)=>a.school.localeCompare(b.school)||a.id.localeCompare(b.id));const ready=state.programs.length>=2&&state.programs.length<=5;
 root.innerHTML=head('把项目放在同一口径下比较','选择 2—5 个培养项目。人数、未知去向与名册完整性一起展示；可以进一步按研究方向和岗位证据筛选。',observatory.as_of)+`<form class="filter-panel obs-form" aria-label="项目比较筛选">${studyControls(state,records)}<details class="obs-program-picker" open><summary>已选 ${state.programs.length} / 5 个项目</summary>${searchField('program_query','查找培养项目',state.program_query)}<div class="obs-program-list">${available.map(p=>`<label><input type="checkbox" name="programs" value="${esc(p.id)}" ${state.programs.includes(p.id)?'checked':''} ${state.programs.length>=5&&!state.programs.includes(p.id)?'disabled':''}><span>${esc(p.school)}<small>${esc(p.kind==='economics'?'Economics / IO':p.kind==='marketing'?'Marketing':p.kind||'项目类型未知')} · ${esc(p.label||p.program||p.id)} · ${esc(labelRegion(p.region))} · ${records.filter(r=>r.program_id===p.id).length} 人</small></span></label>`).join('')}</div></details><p class="obs-context">当前口径：${esc(YEAR_BASES[state.year_basis])} · ${esc(state.year==='all'?'所有年份':state.year)} · ${state.basis==='first'?'首次岗位':'已确认最终安排，其余沿用首职'}。完整性按来源名册成员核验，不能将名单完整解释为去向全部已知。</p></form>`+(ready?panel('项目比较表','SAME BASIS, VISIBLE DENOMINATORS',actions('compare')+`<div class="table-scroll"><table class="obs-table obs-comparison"><thead><tr><th scope="col">指标 / 分母</th>${comparison.map(g=>`<th scope="col">${esc(g.program.school)}<span class="cell-note">${esc(g.program.kind==='economics'?'Economics / IO':'Marketing')} · ${esc(labelRegion(g.program.region))}</span></th>`).join('')}</tr></thead><tbody>${[
 ['已收录人员',g=>g.summary.n],['岗位类型已知 / 已收录',g=>ratio(g.summary.known,g.summary.n)],['学术教职（含规则推定）/ 岗位类型已知',g=>ratio(g.summary.faculty,g.summary.known)],['明确终身轨 / 已收录',g=>ratio(g.summary.confirmed_tt,g.summary.n)],['Tenure 状态未知',g=>g.summary.tenure_unknown],['博士后',g=>g.summary.postdoc],['非终身轨教职',g=>g.summary.non_tt],['业界及其他',g=>g.summary.other],['去向 / 岗位类型未知',g=>g.summary.unknown],['仍在求职 / 延期',g=>`${g.summary.on_market} / ${g.summary.deferred}`],['来源整届已确认 / 已建核验单元',g=>ratio(g.complete,g.cells.length)],['最终安排独立记录 / 沿用首职',g=>state.basis==='final'?`${g.summary.final_verified} / ${g.summary.final_fallback}（另 ${g.summary.final_unobserved} 人无首职结果）`:'当前查看首次岗位'],['查看对应人员',g=>`<button type="button" class="text-button" data-obs-detail="${esc(g.program.id)}">查看 ${g.summary.n} 人与原始来源</button>`]
 ].map(([label,get])=>`<tr><th scope="row">${esc(label)}</th>${comparison.map(g=>`<td>${typeof get(g)==='number'?get(g):String(get(g))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${note('“学术教职”包含公开职位文字支持的学术岗位，Tenure 状态另外核验。零条已收录记录不表示项目没有毕业生；多标签人员在每个项目内只计一次。')}`)+panel('研究主题与方法','RESEARCH PROFILE',`<div class="obs-profile-grid">${comparison.map(g=>`<article><h3>${esc(g.program.school)}</h3>${['topics','methods'].map(kind=>{const tally=new Map();for(const r of g.records){const person=arr(observatory.people).find(p=>p.id===r.id)||r;for(const id of unique(arr(person.research?.[kind]).length?person.research[kind]:arr(r[kind])))tally.set(id,(tally.get(id)||0)+1);}return `<h4>${kind==='topics'?'研究主题':'研究方法'}</h4>${tally.size?`<ul class="obs-mini-bars">${[...tally].sort((a,b)=>b[1]-a[1]).slice(0,8).map(([id,n])=>`<li><span>${esc(canonicalLabel(observatory,kind,id))}</span><strong>${n}</strong><progress max="${Math.max(1,g.records.length)}" value="${n}">${n}</progress></li>`).join('')}</ul>`:'<p class="muted">当前筛选资料尚不足。</p>'}`}).join('')}</article>`).join('')}</div>${note('一人可有多个主题或方法，各标签人数不相加为项目总人数；缺失研究资料者仍保留在项目分母中。')}`)+observationPanel(selected,observatory):empty('请选择 2—5 个培养项目'));
 if(ready&&state.detail){const rows=comparison.find(g=>g.program.id===state.detail)?.records||[];root.insertAdjacentHTML('beforeend',panel('对应人员与证据入口','RECORDS BEHIND THE COMPARISON',peopleTable(rows,observatory,state.basis)));}
 }
 render();bindRoot(root,(type,e)=>{
  if(type==='submit'){e.preventDefault();return}const el=e.target;
  if((type==='change'||type==='input')&&el.name){if(type==='input'&&el.type!=='search')return;if(type==='change'&&el.type==='search')return;if(el.name==='programs'){state.programs=el.checked?unique([...state.programs,el.value]).slice(0,5):state.programs.filter(id=>id!==el.value)}else state[el.name]=el.value;persist('compare',state);withFocus(root,render)}
  if(type==='click'){const person=el.closest('[data-obs-person]');if(person)ctx.onOpenPerson?.(person.dataset.obsPerson);const detail=el.closest('[data-obs-detail]');if(detail){state.detail=detail.dataset.obsDetail;persist('compare',state);render();root.querySelector('.obs-panel:last-child')?.scrollIntoView({block:'start',behavior:'smooth'})}const exp=el.closest('[data-obs-export]');if(exp){const rows=comparison.map(g=>({program_id:g.program.id,school:g.program.school,kind:g.program.kind,...g.summary,complete_cohorts:g.complete,audited_cells:g.cells.length,person_ids:g.records.map(r=>r.id),source_urls:unique(g.records.flatMap(r=>arr(r.sources).map(s=>typeof s==='string'?s:s.url)))}));exportRows('compare',exp.dataset.format,rows,{as_of:observatory.as_of,...state},['program_id','school','kind','n','known','faculty','unknown','postdoc','confirmed_tt','tenure_unknown','complete_cohorts','audited_cells','person_ids','source_urls']);}}
 });
}

function flowSvg(rows,observatory){const shown=rows.slice(0,12),height=shown.length*82+58,max=Math.max(1,...shown.map(g=>g.n));return `<div class="obs-flow-scroll"><svg class="obs-flow-svg" viewBox="0 0 1060 ${height}" width="1060" height="${height}" role="img" aria-labelledby="obs-flow-title obs-flow-desc"><title id="obs-flow-title">培养项目、研究方向与接收院系流向</title><desc id="obs-flow-desc">显示人数最多的 ${shown.length} 条路径。每条路径可用键盘选择，完整数据见下方表格。</desc><text x="18" y="22" class="obs-svg-heading">博士培养项目</text><text x="405" y="22" class="obs-svg-heading">研究方向</text><text x="720" y="22" class="obs-svg-heading">接收机构 / 院系</text>${shown.map((g,i)=>{const y=42+i*82;const width=2+g.n/max*10;return `<a href="#flows" data-obs-flow="${i}" tabindex="0" aria-label="${esc(g.school+'，'+(TRACK_NAMES[g.track]||g.track)+'，'+g.destination+'，'+g.n+'人')}" class="obs-svg-route"><path d="M 320 ${y+25} C 355 ${y+25}, 365 ${y+25}, 395 ${y+25} M 610 ${y+25} C 650 ${y+25}, 665 ${y+25}, 705 ${y+25}" fill="none" stroke="#9ac4b5" stroke-width="${width}"/><rect x="8" y="${y}" width="312" height="57" rx="7" fill="#f5f8f4" stroke="#d4e2d8"/><rect x="395" y="${y+5}" width="215" height="47" rx="7" fill="#e7f0e8"/><rect x="705" y="${y}" width="345" height="57" rx="7" fill="#f5f8f4" stroke="#d4e2d8"/><text x="22" y="${y+23}">${esc(g.school.length>40?g.school.slice(0,38)+'…':g.school)}</text><text x="22" y="${y+43}" class="obs-svg-detail">${g.n} 位研究者</text><text x="409" y="${y+34}">${esc(canonicalLabel(observatory,'tracks',g.track))}</text><text x="719" y="${y+23}">${esc(g.destination.length>42?g.destination.slice(0,40)+'…':g.destination)}</text><text x="719" y="${y+43}" class="obs-svg-detail">${esc(g.department.length>42?g.department.slice(0,40)+'…':g.department)}</text></a>`}).join('')}</svg></div>`;}
function mountFlows(ctx){const {root,records,catalog,observatory}=ctx;const state=restore({year_basis:'source',year:'all',track:ctx.filters?.track||'all',basis:ctx.filters?.basis||'first',complete_only:'all',tenure:'all',provisional:'exclude',region:'all',flow:''});let selected=[],groups=[];
 function render(){selected=selectStudyRecords(records,catalog,observatory,state);groups=flowRows(selected,observatory,state);const known=selected.filter(r=>outcomeOf(r,state.basis,observatory).destination).length;root.innerHTML=head('从培养项目，追踪到接收院系','路径按真实人员记录生成。接收院系缺失时单列，院校名称与职位文字不自动转换为院系。',observatory.as_of)+`<form class="filter-panel obs-form">${studyControls(state,records,{region:true})}</form><div class="obs-stats">${stat('对应人员',selected.length,'人员去重')}${stat('已知去向机构',known,`未知机构 ${selected.length-known} 人`)}${stat('不同路径',groups.length,'同人多方向可出现在多条路径')}${stat('接收机构',unique(groups.filter(g=>g.destination!=='去向尚未核验').map(g=>g.destination)).length,'按所选首次 / 最终口径')}</div>`+panel('培养项目 → 研究方向 → 接收机构 / 院系','FOLLOW THE PEOPLE',groups.length?flowSvg(groups,observatory)+note('窄屏可横向滑动查看完整路径。图中显示人数最多的 12 条路径，线条粗细对应各路径人数。点击路径查看人员；完整路径保留在下方表格。一人多个研究方向时可能出现在多条路径，各路径人数不相加为市场总人数。'):empty('当前筛选没有已收录路径'))+panel('全部流向与原始记录','ACCESSIBLE FLOW TABLE',actions('flows')+(groups.length?`<div class="table-scroll"><table class="obs-table"><thead><tr><th scope="col">培养项目</th><th scope="col">研究方向</th><th scope="col">接收机构 / 院系</th><th scope="col">人数</th><th scope="col">对应人员</th></tr></thead><tbody>${groups.map((g,i)=>`<tr><td>${esc(g.school)}</td><td>${esc(canonicalLabel(observatory,'tracks',g.track))}</td><td>${esc(g.destination)}<span class="cell-note">${esc(g.department)} · ${esc(labelRegion(g.region))}</span></td><td>${g.n}</td><td><button type="button" class="text-button" data-obs-flow="${i}">查看 ${g.n} 人</button></td></tr>`).join('')}</tbody></table></div>`:empty('尚无可显示流向')));if(state.flow!==''&&groups[Number(state.flow)]){const g=groups[Number(state.flow)];root.insertAdjacentHTML('beforeend',panel(`${g.school} → ${g.destination}`,'PEOPLE BEHIND THIS PATH',peopleTable(selected.filter(r=>g.ids.includes(r.id)),observatory,state.basis)));}}
 render();bindRoot(root,(type,e)=>{if(type==='submit'){e.preventDefault();return}if(type==='change'&&e.target.name){state[e.target.name]=e.target.value;state.flow='';persist('flows',state);withFocus(root,render)}if(type==='click'){const target=e.target.closest('[data-obs-flow]');if(target){e.preventDefault();state.flow=target.dataset.obsFlow;persist('flows',state);render();root.querySelector('.obs-panel:last-child')?.scrollIntoView({block:'start',behavior:'smooth'})}const person=e.target.closest('[data-obs-person]');if(person)ctx.onOpenPerson?.(person.dataset.obsPerson);const exp=e.target.closest('[data-obs-export]');if(exp)exportRows('flows',exp.dataset.format,groups,{as_of:observatory.as_of,...state},['program_id','school','track','destination','department','region','n','ids','source_urls']);}});
}

const GAP_LABELS={research_missing:'Marketing 方向待细分',outcome_missing:'首职 / 任职路径待核验',year_missing:'已知首职，年份待核验',role_missing:'机构已知，岗位类别待核验',cv_missing:'缺本人 CV 链接',jmp_missing:'尚无明确 JMP',final_fallback:'未单独核验最终安排',all:'全部人员'};
function qualityGaps(records,observatory){return {research_missing:records.filter(r=>arr(r.tracks).includes('marketing')&&!arr(r.tracks).some(t=>['qm','cb','strategy'].includes(t))).map(r=>r.id),outcome_missing:records.filter(r=>r.status==='outcome_unknown').map(r=>r.id),year_missing:records.filter(r=>r.status==='placed'&&!r.placement_year).map(r=>r.id),role_missing:records.filter(r=>r.destination&&outcomeOf(r,'first',observatory).category==='unknown').map(r=>r.id),cv_missing:records.filter(r=>!r.cv_url).map(r=>r.id),jmp_missing:records.filter(r=>!r.jmp).map(r=>r.id),final_fallback:records.filter(r=>!r.final_placement).map(r=>r.id),all:records.map(r=>r.id)};}
function auditStatus(cell){return cell.cohort_complete?'cohort_verified':cell.roster_status&&AUDIT_NAMES[cell.roster_status]?cell.roster_status:cell.status||'not_started';}
function pagination(page,total,size=30){const max=Math.max(1,Math.ceil(total/size));return `<div class="obs-pagination"><span>${total} 条记录 · 第 ${page} / ${max} 页</span><button type="button" class="button secondary" data-obs-page="${page-1}" ${page<=1?'disabled':''}>上一页</button><button type="button" class="button secondary" data-obs-page="${page+1}" ${page>=max?'disabled':''}>下一页</button></div>`;}
function mountQuality(ctx){const {root,records,catalog,observatory}=ctx;const state=restore({tab:'gaps',gap:'research_missing',status:'all',program:'all',period:'all',age:'all',page:'1',audit:''});let gapRows=[],audits=[],exportable=[];
 const allAudits=arr(observatory.audit).length?observatory.audit:arr(catalog.coverage);const gaps=qualityGaps(records,observatory);const peopleMap=new Map(records.map(r=>[r.id,r]));const programMap=new Map(arr(catalog.programs).map(p=>[p.id,p]));const asOf=observatory.as_of||catalog.updated_at;const conflicts=arr(observatory.quality?.conflicts).length?observatory.quality.conflicts:arr(observatory.claims).filter(c=>c.conflict||c.status==='conflict');
 function render(){const ageOf=r=>{if(!r.checked_at)return null;const value=Math.floor((Date.parse(asOf)-Date.parse(r.checked_at))/86400000);return Number.isFinite(value)?value:null;};gapRows=records.filter(r=>gaps[state.gap]?.includes(r.id)&&(!state.age||state.age==='all'||state.age==='unknown'&&ageOf(r)===null||Number.isFinite(Number(state.age))&&ageOf(r)!==null&&ageOf(r)>=Number(state.age)));audits=allAudits.filter(c=>(state.program==='all'||c.program_id===state.program)&&(state.period==='all'||c.period===state.period)&&(state.status==='all'||auditStatus(c)===state.status));const listing=state.tab==='audit'?audits:state.tab==='conflicts'?conflicts:gapRows;const page=Math.max(1,Math.min(Number(state.page)||1,Math.ceil(listing.length/30)||1));state.page=String(page);exportable=listing;
 const targetIds=new Set([...(catalog.scope?.ranking?.rows||[]),...(catalog.scope?.asia||[])].map(p=>p.program_id));const targetCells=allAudits.filter(c=>targetIds.has(c.program_id));const complete=targetCells.filter(c=>c.cohort_complete).length;const reconciled=targetCells.filter(c=>c.status==='source_reconciled').length;const final=records.filter(r=>r.final_placement).length;
 root.innerHTML=head('让完整性和缺口一起可见','名单完整、来源表对齐、去向已知和字段证据是独立维度。每个汇总都能回到对应人员或年度名册。',asOf)+`<div class="obs-stats">${stat('已收录研究者',records.length,'稳定 ID 去重','data-obs-gap="all"')}${stat('目标范围整届已确认',complete,`${targetCells.length} 个目标年度 / 求职季单元`,'data-obs-tab="audit" data-obs-status="cohort_verified"')}${stat('目标来源表已对齐',reconciled,'来源表对齐仍需独立确认整届完整性','data-obs-tab="audit" data-obs-status="source_reconciled"')}${stat('最终安排独立记录',final,`其余 ${records.length-final} 人尚无独立最终安排`,'data-obs-gap="final_fallback"')}</div>`+panel('字段缺口与资料可用性','DATA QUALITY',`<div class="obs-gap-grid">${Object.entries(GAP_LABELS).filter(([k])=>k!=='all').map(([key,label])=>`<button type="button" class="obs-gap ${state.gap===key&&state.tab==='gaps'?'selected':''}" data-obs-gap="${key}"><strong>${gaps[key].length}</strong><span>${esc(label)}</span><small>${ratio(gaps[key].length,records.length)}</small></button>`).join('')}</div>${note('缺 CV / JMP 表示本库尚未收录相应资料；不表示本人没有 CV 或论文。最终安排未另行确认者，有首职资料时沿用首职；其余保留未知或求职状态，均不表示最终安排已核验。')}`)+`<div class="obs-tabs" role="group" aria-label="质量记录分类">${[['gaps','人员与字段缺口'],['audit','项目年度名册'],['conflicts','冲突与待核验'],['changes','发布变化与范围']].map(([key,label])=>`<button type="button" class="button ${state.tab===key?'':'secondary'}" data-obs-tab="${key}" aria-pressed="${state.tab===key}">${label}</button>`).join('')}</div>`;
 if(state.tab==='gaps')root.insertAdjacentHTML('beforeend',panel(GAP_LABELS[state.gap]||'对应人员','RECORD-LEVEL QUALITY',`<form class="obs-inline-filters">${field('gap','字段缺口',Object.entries(GAP_LABELS),state.gap)}${field('age','最后核验时间',[['all','所有核验时间'],['30','至少 30 天前'],['90','至少 90 天前'],['365','至少一年前'],['unknown','没有核验日期']],state.age)}</form>${actions('quality','对应人员')}${peopleTable(gapRows.slice((page-1)*30,page*30),observatory,'first')}${pagination(page,gapRows.length)}`));
 if(state.tab==='audit'){root.insertAdjacentHTML('beforeend',panel('项目 × 年度 / 求职季','ROSTER AND OUTCOME AUDIT',`<form class="obs-filter-grid obs-form">${field('program','培养项目',[['all','全部发现项目'],...arr(catalog.programs).slice().sort((a,b)=>a.school.localeCompare(b.school)).map(p=>[p.id,p.school+' · '+(p.kind==='economics'?'Economics':'Marketing')])],state.program)}${field('period','年度 / 求职季',[['all','全部已建核验单元'],...unique(allAudits.map(c=>c.period)).sort().map(p=>[p,p])],state.period)}${field('status','名册状态',[['all','全部状态'],...Object.entries(AUDIT_NAMES)],state.status)}</form>${actions('audit')}${audits.length?`<div class="table-scroll"><table class="obs-table"><thead><tr><th scope="col">培养项目 / 项目资格</th><th scope="col">年度 / 名单类型</th><th scope="col">名册完整性</th><th scope="col">录入人数 / 来源人数</th><th scope="col">去向核验</th><th scope="col">来源与成员</th></tr></thead><tbody>${audits.slice((page-1)*30,page*30).map(c=>{const p=programMap.get(c.program_id);const members=arr(c.record_ids).map(id=>peopleMap.get(id)).filter(Boolean);const known=c.outcome_known??members.filter(r=>r.destination&&r.status==='placed').length;return `<tr><td>${esc(p?.school||c.program_id)}<span class="cell-note">${esc(p?.kind==='economics'?'Economics / IO':p?.kind==='marketing'?'Marketing':'项目类型未知')} · ${{verified:'博士项目已确认',pending:'项目资格待核验',not_identified:'尚未识别相关博士项目'}[c.eligibility||p?.eligibility]||'资格待核验'}</span></td><td>${esc(c.period)}<span class="cell-note">${esc(c.year_basis||'年份依据未记录')}</span></td><td>${badge(AUDIT_NAMES[auditStatus(c)]||auditStatus(c))}<span class="cell-note">整届：${c.cohort_complete?'已确认':'尚未确认'}</span></td><td>${members.length} / ${c.listed_count===null||c.listed_count===undefined?'?':c.listed_count}</td><td>${known} 已知 / ${members.length-known} 待核验<span class="cell-note">${c.outcome_complete?'去向完整已确认':'去向完整性未确认'}</span></td><td><button type="button" class="text-button" data-obs-audit="${esc(c.id||c.program_id+'::'+c.period)}">核对来源与 ${members.length} 位成员</button></td></tr>`}).join('')}</tbody></table></div>`:empty('没有符合条件的核验单元')}${pagination(page,audits.length)}${note('来源人数为未知时显示“?”。年度表未开始、尚未公开及资料不足均不代表该年无人毕业。去向已知人数仅描述已录入成员，不替代独立整届分母。')}`));if(state.audit){const c=allAudits.find(c=>(c.id||c.program_id+'::'+c.period)===state.audit);if(c)root.insertAdjacentHTML('beforeend',panel(`${programMap.get(c.program_id)?.school||c.program_id} · ${c.period}`,'AUDIT EVIDENCE',`<div class="obs-body"><p>${esc(c.notes||'尚无核验说明')}</p>${c.completeness_evidence?`<p>${esc(typeof c.completeness_evidence==='string'?c.completeness_evidence:JSON.stringify(c.completeness_evidence))}</p>`:''}<p>核验于 ${esc(c.checked_at||'尚未记录')} · 名册完整性 ${c.cohort_complete?'已确认':'未确认'}</p>${sources(c.sources)}</div>${peopleTable(arr(c.record_ids).map(id=>peopleMap.get(id)).filter(Boolean),observatory,'first')}`));}}
 if(state.tab==='conflicts'){root.insertAdjacentHTML('beforeend',panel('字段冲突与研究线索','REVIEW BEFORE WRITING FACTS',actions('conflicts')+(conflicts.length?`<div class="obs-body">${conflicts.slice((page-1)*30,page*30).map(c=>`<article class="obs-conflict"><h3>${peopleMap.has(c.person_id)?personButton(peopleMap.get(c.person_id)):esc(c.person_id||c.id)} · ${esc(c.field?fieldName(c.field):'待核验字段')}</h3><p>${esc(typeof c.conflict==='string'?c.conflict:JSON.stringify(c.conflict||c))}</p>${sources(c.source_urls||c.sources)}</article>`).join('')}</div>${pagination(page,conflicts.length)}`:'<p class="obs-body muted">当前没有结构化冲突记录。已有来源差异可能仍保留在原始备注中；这不等于所有字段均已一致。</p>')+`<details class="obs-body"><summary>维护待核验队列 · ${arr(observatory.queue).length} 条</summary>${arr(observatory.queue).length?`<pre class="obs-json">${esc(JSON.stringify(observatory.queue,null,2))}</pre>`:'<p>本次生成时队列为空。来源检测结果另存为工作流产物，未经核验不会覆盖人员事实。</p>'}</details>`));}
 if(state.tab==='changes'){root.insertAdjacentHTML('beforeend',sourceCheckMarkup(observatory));const release=observatory.release||{};const io=observatory.io_scope||{};root.insertAdjacentHTML('beforeend',panel('本次发布变化','GENERATED FROM DATA',`<div class="obs-body"><p>观察日期：${esc(asOf)} · 数据模型 ${esc(observatory.schema_version||'未记录')}</p><p>完整名单已确认 ${allAudits.filter(c=>c.cohort_complete).length} 个单元；当前 ${records.length} 位人员、${normalizedJobs(observatory,catalog).length} 条招聘广告。</p><details open><summary>基线与本次变化</summary><pre class="obs-json">${esc(JSON.stringify(release,null,2))}</pre></details></div>`)+panel('Marketing 与 Economics IO 的独立覆盖范围','VERSIONED SCOPE',`<div class="obs-body"><p>Marketing：${esc(catalog.scope?.label||'现有固定范围')}；排名快照 ${esc(catalog.scope?.id||'未记录')}。</p><p>Economics IO：${esc(io.label||io.id||'独立范围核验中')}。</p><p>${esc(typeof io.selection==='string'?io.selection:JSON.stringify(io.selection||'以公开项目资料核实，不沿用 Marketing 排名。'))}</p><p>${arr(io.program_ids).length} 个 IO 培养项目列入独立范围。</p>${sources(io.sources)}${io.notes?`<p>${esc(typeof io.notes==='string'?io.notes:JSON.stringify(io.notes))}</p>`:''}<details><summary>研究分类词表与别名</summary><div class="obs-taxonomy">${['tracks','topics','methods'].map(kind=>`<section><h3>${{tracks:'方向',topics:'主题',methods:'方法'}[kind]}</h3>${arr(observatory.taxonomy?.[kind]).map(t=>`<p><strong>${esc(t.label)}</strong> <code>${esc(t.id)}</code><br>${esc(t.definition||'')}<span class="cell-note">${esc(arr(t.aliases).join(' / '))}</span></p>`).join('')}</section>`).join('')}</div></details></div>`));}
 }
 render();bindRoot(root,(type,e)=>{if(type==='submit'){e.preventDefault();return}if(type==='change'&&e.target.name){state[e.target.name]=e.target.value;state.page='1';state.audit='';persist('quality',state);withFocus(root,render)}if(type==='click'){const el=e.target;const person=el.closest('[data-obs-person]');if(person)ctx.onOpenPerson?.(person.dataset.obsPerson);const gap=el.closest('[data-obs-gap]');const tab=el.closest('[data-obs-tab]');const page=el.closest('[data-obs-page]');const audit=el.closest('[data-obs-audit]');if(gap||tab||page||audit){if(gap){state.gap=gap.dataset.obsGap;state.tab='gaps';state.page='1'}if(tab){state.tab=tab.dataset.obsTab;state.status=tab.dataset.obsStatus||'all';state.page='1'}if(page)state.page=page.dataset.obsPage;if(audit)state.audit=audit.dataset.obsAudit;persist('quality',state);render();if(audit)root.querySelector('.obs-panel:last-child')?.scrollIntoView({block:'start',behavior:'smooth'})}const exp=el.closest('[data-obs-export]');if(exp){if(exp.dataset.obsExport==='sources'){exportRows('sources',exp.dataset.format,arr(observatory.source_checks?.sources),{as_of:asOf,last_run:observatory.source_checks?.last_run},['url','fetched_at','last_success_at','http_status','changed','error','sha256','etag','last_modified','snapshot_path','history']);return;}const columns=state.tab==='audit'?['program_id','period','status','roster_status','cohort_complete','listed_count','record_ids','outcome_known','outcome_unknown','outcome_complete','checked_at','sources','notes']:state.tab==='conflicts'?['person_id','field','status','value','conflict','source_urls','checked_at']:['id','name','school','program_id','source_cohort_year','graduation_year','placement_year','status','destination','role','checked_at','sources'];exportRows(exp.dataset.obsExport,exp.dataset.format,exportable,{as_of:asOf,...state},columns)}}});
}

const JOB_FAMILIES={academic:'大学教研岗位',faculty:'大学教研岗位',postdoc:'博士后',research:'研究岗位',teaching:'教学岗位',industry:'企业岗位',government:'政府 / 公共机构',visiting:'访问岗位',other:'其他',unknown:'岗位类型待核验'};
const JOB_STATES={active:'公开资料显示在招',historical:'历史 / 已截止',unknown:'状态待核验'};
function mountJobs(ctx){const {root,records,catalog,observatory}=ctx;const jobs=normalizedJobs(observatory,catalog);const state=restore({q:'',cycle:'all',region:'all',track:'all',status:'all',family:'all',institution:'all',title:'all',page:'1'});let selected=[];
 function render(){selected=filterJobs(jobs,state,observatory.as_of);const maxPages=Math.max(1,Math.ceil(selected.length/20));const page=Math.max(1,Math.min(Number(state.page)||1,maxPages));state.page=String(page);const declared=selected.filter(j=>j.positions!==null);const positions=declared.reduce((sum,j)=>sum+j.positions,0);const supply=selectStudyRecords(records,catalog,observatory,{year_basis:'market',year:state.cycle==='all'?'all':state.cycle.slice(0,4),track:state.track,basis:'first'});const historical=selectStudyRecords(records,catalog,observatory,{year_basis:'placement',year:state.cycle==='all'?'all':state.cycle.slice(0,4),track:state.track,basis:'first'});root.innerHTML=head('把招聘需求与已观察到的去向放在一起','保留原始公告和核验时间。广告、明确招聘人数和实际聘用人数各自统计；公开岗位来源也有覆盖边界。',observatory.as_of)+`<form class="filter-panel obs-form"><div class="obs-filter-grid">${searchField('q','搜索机构、院系或职位',state.q)}${field('cycle','招聘季',[['all','全部招聘季'],...unique(jobs.map(j=>j.cycle)).sort().reverse().map(v=>[v,v])],state.cycle)}${field('region','招聘地区',[['all','全部地区'],...unique(jobs.map(j=>j.region)).sort().map(v=>[v,labelRegion(v)])],state.region)}${field('track','研究方向',[['all','全部方向'],...Object.entries(TRACK_NAMES)],state.track)}${field('status','岗位状态',[['all','全部公开状态'],...Object.entries(JOB_STATES)],state.status)}${field('family','岗位类型',[['all','全部岗位类型'],...unique(jobs.map(j=>j.job_family)).map(v=>[v,JOB_FAMILIES[v]||v])],state.family)}${field('institution','招聘机构',[['all','全部机构'],...unique(jobs.map(j=>j.institution)).sort().map(v=>[v,v])],state.institution)}${field('title','原始职级 / 职位',[['all','全部职级'],...unique(jobs.map(j=>j.title)).sort().map(v=>[v,v])],state.title)}</div></form><div class="obs-stats">${stat('去重招聘广告',selected.length,'一条广告可能招聘多名或零名人员')}${stat('明确招聘人数合计',declared.length?positions:'未披露',`${declared.length} 条广告披露人数，其余未知`)}${stat('招聘机构',unique(selected.map(j=>j.institution_id||j.institution)).length,'按规范机构标识去重')}${stat('公开资料显示在招',selected.filter(j=>jobState(j,observatory.as_of)==='active').length,'按观察日期及公告状态')}</div>`+panel('招聘公告与原始资料','PUBLIC JOB ADVERTISEMENTS',actions('jobs')+(selected.length?`<div class="obs-job-cards">${selected.slice((page-1)*20,page*20).map(j=>`<article class="obs-job-card"><div class="obs-job-head"><div><p class="eyebrow">${esc(labelRegion(j.region))} / ${esc(j.cycle||'招聘季未核验')}</p><h3>${esc(j.institution)}</h3><p>${esc(j.department||'院系未核验')}</p></div>${badge(JOB_STATES[jobState(j,observatory.as_of)])}</div><h4>${esc(j.title||'职位名称未核验')}</h4><div>${j.tracks.map(t=>badge(canonicalLabel(observatory,'tracks',t))).join('')}${badge(TENURE_NAMES[j.tenure_status]||j.tenure_status||'Tenure 状态未知')}</div><dl class="obs-job-dates"><div><dt>发布日期</dt><dd>${esc(j.published_at||'未披露')}</dd></div><div><dt>截止日期</dt><dd>${esc(j.deadline||'未披露 / 滚动招聘')}</dd></div><div><dt>明确招聘人数</dt><dd>${j.positions===null?'未知':j.positions}</dd></div><div><dt>资料核验</dt><dd>${esc(j.checked_at||'未记录')}</dd></div></dl><p class="obs-job-evidence">${esc(typeof j.evidence==='object'?JSON.stringify(j.evidence):j.evidence||'原始公告所支持的职位资料；未公开字段保持未知。')}</p>${sources(j.sources)}${arr(j.aliases).length?`<details><summary>重复公告与别名</summary><p>${esc(j.aliases.join(' · '))}</p></details>`:''}</article>`).join('')}</div>`:empty('没有符合条件的已收录招聘公告'))+pagination(page,selected.length,20))+panel('供给、招聘需求与实际流向：并列观察','MATCHED LABELS, DISTINCT POPULATIONS',`<div class="obs-window-grid"><article><h3>已收录公开求职名册</h3><strong>${supply.filter(r=>r.market_cycle).length}<small> 位人员</small></strong><p>按${state.cycle==='all'?'所有已收录求职季':esc(state.cycle)}及研究方向筛选，包含已获岗位但保留求职季的人员。</p></article><article><h3>当前招聘筛选</h3><strong>${selected.length}<small> 条广告</small></strong><p>${declared.length?positions+' 个明确招聘名额；':'招聘人数尚无公开值；'}${selected.length-declared.length} 条广告人数未公开。机构、地区和岗位筛选仅作用于招聘端。</p></article><article><h3>已收录首职结果</h3><strong>${historical.filter(r=>r.destination&&r.placement_year).length}<small> 位人员</small></strong><p>按${state.cycle==='all'?'所有已知首职年份':esc(state.cycle.slice(0,4))+' 首职年'}及研究方向筛选。求职季与首职年并非相同 cohort。</p></article></div>${note('三组数据按统一研究标签并列展示，来源、时间口径和覆盖范围分别保留。它们不是同一总体的分子分母，不据此计算供需比、就业率或个人成功概率。广告截止不证明已聘用；同一岗位的跨平台公告应先人工核对去重。')}`);
 }
 render();bindRoot(root,(type,e)=>{if(type==='submit'){e.preventDefault();return}if((type==='change'||type==='input')&&e.target.name){if(type==='input'&&e.target.type!=='search')return;if(type==='change'&&e.target.type==='search')return;state[e.target.name]=e.target.value;state.page='1';persist('jobs',state);withFocus(root,render)}if(type==='click'){const p=e.target.closest('[data-obs-page]');if(p){state.page=p.dataset.obsPage;persist('jobs',state);render()}const exp=e.target.closest('[data-obs-export]');if(exp)exportRows('jobs',exp.dataset.format,selected,{as_of:observatory.as_of,...state},['id','institution','institution_id','department','region','tracks','title','job_family','tenure_status','cycle','published_at','deadline','status','positions','checked_at','sources','evidence','aliases']);}});
}

export function mountObservatory(view,ctx){
 if(!['quality','compare','flows','jobs'].includes(view))return false;
 unmountObservatory(ctx.root);ctx.root.dataset.observatoryView=view;ctx.records=arr(ctx.records);ctx.catalog=ctx.catalog||{};ctx.observatory=ctx.observatory||{};
 ({quality:mountQuality,compare:mountCompare,flows:mountFlows,jobs:mountJobs})[view](ctx);
 return true;
}
